#!/usr/bin/env node
// Fails if the IDL generated by the current build differs from the committed
// copy the testbench uses. Generated artifacts are never hand-edited: regenerate
// with `anchor idl build -p ch_core -o target/idl/ch_core.json -t target/types/ch_core.ts -- --features mock-oracle,dev-venue-signer`
// and `npm --prefix testbench run sync-idl`.
// Usage: node scripts/ci/check-idl.cjs [generated] [committed]   (from clearinghouse/)
const fs = require("fs");
const path = require("path");

const root = path.resolve(__dirname, "../..");
const generated = path.resolve(process.argv[2] ?? path.join(root, "target/idl/ch_core.json"));
const committed = path.resolve(process.argv[3] ?? path.join(root, "testbench/src/idl/ch_core.json"));

if (!fs.existsSync(generated)) {
  console.error(`FAIL: generated IDL not found at ${generated}. Build it first.`);
  process.exit(1);
}
const canon = (p) => JSON.stringify(JSON.parse(fs.readFileSync(p, "utf8")), null, 2);
const a = canon(generated);
const b = canon(committed);
if (a !== b) {
  const al = a.split("\n");
  const bl = b.split("\n");
  const i = al.findIndex((line, k) => line !== bl[k]);
  console.error(`FAIL: committed IDL differs from the build output (first difference at line ${i + 1}):`);
  console.error(`  generated: ${al[i]}`);
  console.error(`  committed: ${bl[i]}`);
  process.exit(1);
}
console.log("ok  committed IDL matches the build output");

// The generated TypeScript type the testbench compiles against.
if (process.argv[2] === undefined) {
  const genTypes = path.join(root, "target/types/ch_core.ts");
  const comTypes = path.join(root, "testbench/src/idl/ch_core.ts");
  const norm = (p) => fs.readFileSync(p, "utf8").replace(/\r\n/g, "\n");
  if (!fs.existsSync(genTypes)) {
    console.error(`FAIL: generated types not found at ${genTypes}. Build the IDL with -t first.`);
    process.exit(1);
  }
  if (!fs.existsSync(comTypes) || norm(genTypes) !== norm(comTypes)) {
    console.error("FAIL: testbench/src/idl/ch_core.ts differs from target/types/ch_core.ts. Run `npm --prefix testbench run sync-idl`.");
    process.exit(1);
  }
  console.log("ok  committed IDL type matches the build output");
}
